  "content.c2d": "NVDA, JAWS এবং VoiceOver স্ক্রিন রিডার ব্যবহার করে আত্মবিশ্বাসের সাথে ডিভাইস নেভিগেট করতে শিখুন।",
  "content.c3": "ব্রেইল সাক্ষরতার বেসিকস",
  "content.c3d": "শুরুর জন্য সাজানো পাঠের মাধ্যমে ব্রেইল পড়া ও লেখা শুরু করুন।",
  "content.c4": "অ্যাডাপ্টিভ টেকনোলজি ওয়ার্কশপ",
  "content.c4d": "ম্যাগনিফায়ার, ভয়েস অ্যাসিস্ট্যান্ট এবং স্মার্ট সহজলভ্যতা টুলস দিয়ে হাতে-কলমে প্রশিক্ষণ।",
  "content.a1": "সহজলভ্যতা দিয়ে শুরু",
  "content.a1d": "দিনের শুরু থেকেই আপনার ডিজিটাল জীবনকে আরও সহজলভ্য করতে জরুরি টিপস।",
  "content.a2": "রঙের কনট্রাস্টের সেরা অনুশীলন",
  "content.a2d": "সঠিক রঙের কনট্রাস্ট কীভাবে সবার জন্য পড়ার সুবিধা বাড়ায়।",
  "content.a3": "কিবোর্ড নেভিগেশন প্যাটার্ন",
  "content.a3d": "দক্ষ ব্রাউজিংয়ের জন্য কিবোর্ড শর্টকাট এবং ট্যাব নেভিগেশন আয়ত্ত করুন।",
  "content.a4": "অন্তর্ভুক্তিমূলক নকশার নীতিমালা",
  "content.a4d": "সহজলভ্যতাকে কেন্দ্রে রাখে এমন ডিজাইন থিংকিং কৌশল।",
  "content.a5": "ARIA লেবেল ঠিকভাবে",
  "content.a5d": "অর্থবহ ARIA অ্যাট্রিবিউট এবং স্ক্রিন রিডার সাপোর্টের জন্য ডেভেলপার গাইড।",
  "content.p1": "আজকের সহজলভ্যতা",
  "content.p1d": "সহজলভ্যতার পক্ষের সমর্থক, টেক লিডার ও ব্যবহারকারীদের সঙ্গে সাপ্তাহিক আলোচনা।",
  "content.p2": "অন্তর্ভুক্তিমূলক কণ্ঠস্বর",
  "content.p2d": "বিশ্বজুড়ে দৃষ্টিপ্রতিবন্ধী ব্যক্তিদের গল্প ও অভিজ্ঞতা।",
  "content.p3": "বাধাহীন প্রযুক্তি",
  "content.p3d": "উদীয়মান প্রযুক্তি কীভাবে প্রতিবন্ধী মানুষের জন্য বাধা দূর করছে তা অন্বেষণ করুন।",
  "content.m1": "অডিও ডেসক্রাইবড ডকুমেন্টারি",
  "content.m1d": "নিঃশব্দ নয়—ডুবে থাকার মতো অভিজ্ঞতার জন্য পূর্ণ অডিও বর্ণনাসহ ডকুমেন্টারি।",
  "content.m2": "সাইন ল্যাঙ্গুয়েজ টিউটোরিয়াল",
  "content.m2d": "ক্যাপশন্ড, হাই-কনট্রাস্ট ভিডিও পাঠের মাধ্যমে সাইন ল্যাঙ্গুয়েজ শিখুন।",
  "content.m3": "সহজলভ্য কোডিং টিউটোরিয়াল",
  "content.m3d": "স্ক্রিন রিডার ব্যবহারকারীদের জন্য ধাপে ধাপে কোডিং পাঠ।",
