  "kids.explorer.eco.lights.explain": "ঘর ছেড়ে গেলে বাতি বন্ধ করলে শক্তি সাশ্রয় হয়।",
  "kids.explorer.eco.lights.explainWrong": "ফাঁকা ঘরে বাতি জ্বালিয়ে রাখলে বিদ্যুৎ নষ্ট হয়।",
  "kids.explorer.eco.ride.prompt": "আপনাকে কাছাকাছি কোথাও যেতে হবে। আপনি কীভাবে সেখানে যাবেন?",
