  "kids.explorer.eco.ride.explainWrong": "গাড়ি জ্বালানি ব্যবহার করে এবং দূষণ তৈরি করে — ছোট দূরত্বে হাঁটা বা সাইকেল চালানো বেশি পরিষ্কার।",
  "kids.explorer.eco.tree.prompt": "আপনার স্কুল একটি বাগান করার পরিকল্পনা করছে। এতে কী থাকা উচিত?",
  "kids.explorer.eco.tree.plant": "নতুন গাছ লাগান",
