  "kids.explorer.eco.bag.explainWrong": "একবার ব্যবহারযোগ্য প্লাস্টিকের ব্যাগ প্রচুর বর্জ্য তৈরি করে — পুনর্ব্যবহারযোগ্য ব্যাগই ভালো।",
  "kids.explorer.eco.animal.prompt": "আপনি গাছের মধ্যে একটি বুনো পাখির বাসা দেখছেন। আপনি কী করবেন?",
