  "kids.explorer.eco.animal.explainWrong": "বুনো বাসা ছুঁলে বাবা-মা পাখিরা ভয় পেয়ে চলে যেতে পারে — তাই শুধু পর্যবেক্ষণ করাই সবচেয়ে ভালো।",
